<script setup lang="ts">
import { ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { api, mutation, ApiError } from '../api/client'
const props=defineProps<{snapshotId:string}>()
type Fact={requirement_id:string;importance:string;review_status:string;origin:string;expression:unknown;evidence:{quote:string;start:number;end:number};[key:string]:unknown}
type Data={contract_artifact_id:string;snapshot:{posting_id:string;source:{source_capture_id:string;provider:string;read_status:string};job:Record<string,unknown>;quality:{normalization_status:string;issues:string[]};document:{canonical_text:string}};facts:{fact:Fact;review:unknown}[]}
const data=ref<Data|null>(null),missing=ref(false),raw=ref(''),editing=ref<Fact|null>(null),expression=ref(''),reason=ref(''),busy=ref(false)
const write=mutation()
async function load(){data.value=null;missing.value=false;raw.value='';try{data.value=await api(`/job-data/source-snapshots/${props.snapshotId}`)}catch(e){if(e instanceof ApiError&&e.status===404)missing.value=true;else ElMessage.error(String(e))}}
watch(()=>props.snapshotId,load,{immediate:true})
async function normalize(){try{await write(`/job-data/source-snapshots/${props.snapshotId}/normalize`,'POST',{});await load()}catch(e){ElMessage.error(String(e))}}
async function readRaw(){if(!data.value)return;try{const capture=await api<{raw_payload:string|null}>(`/job-data/artifacts/${data.value.snapshot.source.source_capture_id}`);raw.value=capture.raw_payload??'原始字节已不可用'}catch(e){ElMessage.error(String(e))}}
function edit(f:Fact){editing.value=JSON.parse(JSON.stringify(f)) as Fact;expression.value=JSON.stringify(f.expression,null,2);reason.value=''}
async function save(){if(!editing.value)return;busy.value=true;try{await write(`/job-data/facts/${editing.value.requirement_id}/versions`,'POST',{expected_fact_id:editing.value.requirement_id,correction:{...editing.value,expression:JSON.parse(expression.value)},reason:reason.value});editing.value=null;await load();ElMessage.success('已保存新的要求版本；已有报告保持原版本，需重新生成统计')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
</script>
<template><section class="contract-panel"><h3>岗位标准化 · V1.1</h3><template v-if="data"><p>{{data.snapshot.source.provider}} · {{data.snapshot.source.read_status}} · {{data.snapshot.quality.normalization_status}}</p><el-alert v-for="issue in data.snapshot.quality.issues" :key="issue" :title="issue" type="info" :closable="false"/><el-collapse><el-collapse-item title="标准岗位字段与版本身份"><pre>{{JSON.stringify({posting_id:data.snapshot.posting_id,...data.snapshot.job},null,2)}}</pre></el-collapse-item><el-collapse-item title="规范正文"><pre>{{data.snapshot.document.canonical_text}}</pre></el-collapse-item><el-collapse-item title="原始输入（文本展示）"><el-button @click="readRaw">读取原始内容</el-button><pre>{{raw}}</pre></el-collapse-item></el-collapse><p>规则提取不自动确认为事实。核对原文和 AND/OR 逻辑后，编辑并确认；只有明确、已确认的要求进入正式统计。</p><article v-for="row in data.facts" :key="row.fact.requirement_id"><el-tag>{{row.fact.importance}}</el-tag> <el-tag>{{row.fact.review_status}}</el-tag><blockquote>{{row.fact.evidence.quote}}</blockquote><small>Unicode 字符区间 [{{row.fact.evidence.start}}, {{row.fact.evidence.end}})</small><pre>{{JSON.stringify(row.fact.expression,null,2)}}</pre><el-button @click="edit(row.fact)">核对 / 修订要求</el-button></article><el-empty v-if="!data.facts.length" description="未识别到要求；规则覆盖有限，请补充清晰的任职要求正文。"/></template><template v-else-if="missing"><p>历史来源尚未标准化；回填只保留已有规范文本，不冒充原始抓取，不进入正式分母。可重新导入完整原文。</p><el-button @click="normalize">生成历史兼容快照</el-button></template><el-dialog :model-value="!!editing" title="要求核对与版本修订" width="min(680px,95vw)" @close="editing=null"><template v-if="editing"><blockquote>{{editing.evidence.quote}}</blockquote><el-form label-position="top"><el-form-item label="重要性"><el-select v-model="editing.importance"><el-option v-for="v in ['required','preferred','responsibility','unknown']" :key="v" :value="v" :label="v"/></el-select></el-form-item><el-form-item label="审核状态"><el-select v-model="editing.review_status"><el-option v-for="v in ['confirmed','pending_review','rejected']" :key="v" :value="v" :label="v"/></el-select></el-form-item><el-form-item label="逻辑表达式（concept / constraint / all_of / any_of）"><el-input v-model="expression" type="textarea" :rows="9"/></el-form-item><el-form-item label="核对或修订原因"><el-input v-model="reason"/></el-form-item></el-form><el-button type="primary" :disabled="!reason.trim()" :loading="busy" @click="save">保存要求新版本</el-button></template></el-dialog></section></template>
<style scoped>.contract-panel{margin-top:24px;border-top:1px solid #ddd;padding-top:16px}.contract-panel article{padding:18px 0;border-bottom:1px solid #ddd}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:360px;overflow:auto}blockquote{border-left:3px solid #6a8;padding-left:12px;white-space:pre-wrap}</style>
